":"flex-start","margin":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"space_between_widgets":10,"space_between_widgets_tablet":10},"elements":[{"id":"3c918c26","elType":"widget","settings":{"editor":"The New Einstein’s Academy offers an innovative program for children. The curriculum is designed to empower the children through social interaction, play, discussion, reflection, and creativity. It is the best preschool in Chicago. The daily program of New Einstein’s Academy includes free play, hands-on activities, many learning and outdoor activities. The preschool also goes on field trips on a bi-monthly basis.","typography_typography":"custom","_margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"text-editor"},{"id":"491e9b3a","elType":"widget","settings":{"blockquote_skin":"quotation","alignment":"left","blockquote_content":"It's always better to start them on easier books, because then they feel successful, and that spurs them on, so they'll read more.","author_name":"John Doe","tweet_button_skin":"link","tweet_button_label":"Post on twitter","button_color_source":"custom","button_text_color":"var(--vamtam-accent-color-2)","button_text_color_hover":"var(--vamtam-accent-color-2)","box_padding":{"unit":"px","size":43,"sizes":[]},"box_border_width":{"unit":"px","top":"1","right":"1","bottom":"1","left":"1","isLinked":true},"box_border_radius":{"unit":"px","size":10,"sizes":[]},"quote_text_color":"var(--vamtam-accent-color-6)","quote_size":{"unit":"px","size":1.6,"sizes":[]},"quote_gap":{"unit":"px","size":0,"sizes":[]},"_margin":{"unit":"%","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"_padding":{"unit":"%","top":"0","right":"15","bottom":"3","left":"15","isLinked":false},"user_name":"@vamtam","author_text_color":"var(--vamtam-accent-color-6)","button_typography_typography":"custom","custom_css":"blockquote .wp-block-pullquote__citation, blockquote .w