    margin: 0;
}","content_gap":{"unit":"px","size":0,"sizes":[]},"tweet_button_view":"icon","content_typography_typography":"custom","content_typography_font_size":{"unit":"px","size":21,"sizes":[]},"content_typography_line_height":{"unit":"em","size":1.63,"sizes":[]},"__globals__":{"box_background_color":"globals/colors?id=vamtam_accent_8"}},"elements":[],"widgetType":"blockquote"},{"id":"105ab148","elType":"widget","settings":{"editor":"Quinn says. Dr. Seuss books, with their rhymes and simple words, are perfect for this age, Quinn says. Kids learn through repetition, so read the same favorite books over and over, ask questions, and encourage your child to say simple words aloud. Throughout the day, have her say the words she sees on street signs, billboards, and computer screens, or have her search for high-frequency words in a magazine.","typography_typography":"custom","text_columns":"1","text_columns_tablet":"1","text_columns_mobile":"1","column_gap":{"unit":"%","size":5,"sizes":[]},"_margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_margin":{"unit":"px","top":"0","right":"0","bottom":"20","left":"0","isLinked":false}},"elements":[],"widgetType":"text-editor"},{"id":"9dc55b","elType":"section","settings":{"content_position":"middle","structure":"20","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[{"id":"65c0e81d","elType":"column","settings":{"_column_size":50,"_inline_size":null,"space_between_widgets":0,"border_border":"solid","border_width":{"unit":"px","top":"1","right":"1","bottom":"1","left":"1","isLinked":true},"color_link":"var(--vamtam-accent-color-6)","color_link_hover":"var(--vamtam-accent-color-2)","margin":{"unit":"px","top":"0","right":"15","bottom":"0","left":"0","isLinked":false},"padding":{"unit":"px","top":"30","right":"20","bottom":"20","left":"30","isLinked":false},"border_color":"var(--vamtam-accent-color-4)","_inline_size_tablet":50,"margin_tablet":{"unit":"px","top":"0","right":"10","bottom":"0","left":"0","isLinked":false},"margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"padding_mobile":{"unit":"px","top":"20","right":"20","bottom":"20","left":"20","isLinked":true},"padding_tablet":{"unit":"px","top":"30","right":"20","bottom":"20","left":"20","isLinked":false}},"elements":[{"id":"75a5fe2","elType":"widget","settings":{"title":"Recent Posts","header_size":"h4","typography_typography":"custom","_margin":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_margin_tablet":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"heading"},{"id":"75986e02","elType":"widget","settings":{"width":{"unit":"%","size":27,"sizes":[]},"text":"Divider","color":"var(--vamtam-accent-color-2)","weight":{"unit":"px","size":3,"sizes":[]},"gap":{"unit":"px","size":7,"sizes":[]},"_margin":{"unit":"px","top":"0","right":"0","bottom":"10","left":"0","isLinked":false},"width_mobile":{"unit":"%","size":37,"sizes":[]},"width_tablet":{"unit":"%","size":38,"sizes":[]}},"elements":[],"widgetType":"divider"},{"id":"e9e6073","elType":"widget","settings":{"wp":{"title":"","number":"5"},"_padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_margin":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_padding_tablet":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_margin_tablet":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"wp-widget-recent-posts"}],"isInner":true},{"id":"307122f3","elType":"column","settings":{"_column_size":50,"_inline_size":null,"content_position":"top","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"15","isLinked":false},"_inline_size_tablet":50,"margin_tablet":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"margin_mobile":{"unit":"px","top":"10","right":"0","bottom":"0","left":"0","isLinked":false},"padding_tablet":{"unit":"px","top":"0","right":"0","bottom":"0","left":"10","isLinked":false},"padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"margin":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[{"id":"53a5a516","elType":"widget","settings":{"editor":"<p>They will also write short, simple sentences such as "The cat ran home." Keep a special box or bin at home filled with writing materials (crayons, pencils, markers, paper, and notepads) so your child can practice writing simple sentences about special things he's done or seen during the day. Ask about what he's written, and have him read it aloud. Offer encouragement by displaying his writings on the refrigerator or on her bedroom wall.</p>","typography_typography":"custom","_margin_tablet":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_padding_tablet":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"text-editor"}],"isInner":true}],"isInner":true},{"id":"36b68175","elType":"widget","settings":{"editor":"Kids this age will learn to recognize, write, order, and count objects up to the number 30. They will be able to add and subtract small numbers (add with a sum of 10 or less and subtract from 10 or less); this focus on addition and subtraction will continue through second grade.","typography_typography":"custom","_margin":{"unit":"px","top":"30","right":"0","bottom":"0","left":"0","isLinked":false},"_margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"text-editor"},{"id":"5b28b300","elType":"widget","settings":{"title":"Numbers and Counting","header_size":"h3"},"elements":[],"widgetType":"heading"},{"id":"77ea101f","elType":"widget","settings":{"editor":"<p>Get your kindergartner to look for the numbers one through 30 in magazines and newspapers. He can cut them out, glue them on paper, and put them in order. When you're riding in the car or waiting in line, play a game of "What comes next?" Give your child a number and ask him to identify the following number. At bedtime, ask him to count how many stuffed animals he has, and ask, "How many books about dogs do you have? How fast can you count them?" Take two of these books away and ask, "How many are left?"</p>
<ul>
<li>Kids this age will learn to recognize, write, order, and count objects up to the number 30.</li>
<li>They will be able to add and subtract small numbers (add with a sum of 10 or less and subtract from 10 or less); this focus on addition and subtraction will continue through second grade.</li>
<li>Kids will learn how to name and describe common shapes (circle, square, triangle, rectangle) and to identify, sort, and classify objects by color, size, and shape.</li>
</ul>","typography_typography":"custom","text_columns":"1","text_columns_tablet":"1","text_columns_mobile":"1","column_gap":{"unit":"%","size":5,"sizes":[]},"_margin":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"text-editor"},{"id":"253f9d31","elType":"section","settings":{"content_position":"top","structure":"20","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[{"id":"4115b71c","elType":"column","settings":{"_column_size":50,"_inline_size":null,"margin":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_inline_size_tablet":50,"padding_tablet":{"unit":"px","top":"0","right":"10","bottom":"0","left":"0","isLinked":false}},"elements":[{"id":"4ddd9196","elType":"widget","settings":{"editor":"<p>Help your child understand the concept of time by saying what time it is during routine activities. Use and explain words like morning, noon, night, yesterday, today, and tomorrow. Make a timeline together showing a typical day, with drawings of regular events and the time of day written beneath each one.</p>","typography_typography":"custom","_margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"text-editor"}],"isInner":true},{"id":"74efac30","elType":"column","settings":{"_column_size":50,"_inline_size":null,"space_between_widgets":10,"margin":{"unit":"px","top":"0","right":"0","bottom":"0","left":"30","isLinked":false},"padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_inline_size_tablet":50,"margin_tablet":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"padding_tablet":{"unit":"px","top":"0","right":"0","bottom":"0","left":"10","isLinked":false},"padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[{"id":"4f70ed5","elType":"widget","settings":{"image":{"url":"https://skole.vamtam.com/wp-content/uploads/2020/01/h-04.jpg","id":1207},"image_border_radius":{"unit":"px","top":"15","right":"15","bottom":"15","left":"15","isLinked":true}},"elements":[],"widgetType":"image"}],"isInner":true}],"isInner":true},{"id":"4b4db10e","elType":"widget","settings":{"editor":"In addition to learning about time, 5- and 6-year-olds can name the four seasons, so chart changes in the weather together on a special weather calendar to help your child learn how the seasons change. Find pictures illustrating the seasons (colorful leaves, snow, blooming flowers) and discuss what your child sees in them. Talk about what clothing you can both wear during each season.","typography_typography":"custom","_margin_mobile":{"unit":"px","top":"20","right":"0","bottom":"0","left":"0","isLinked":false},"_margin":{"unit":"px","top":"20","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"text-editor"}],"isInner":false}],"isInner":false}]

[{"id":"4b0a2397","elType":"section","settings":{"margin_tablet":{"unit":"px","top":"0","right":0,"bottom":"0","left":0,"isLinked":false},"padding_tablet":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"content_width":{"unit":"px","size":1000,"sizes":[]},"margin":{"unit":"px","top":"","right":0,"bottom":"","left":0,"isLinked":true},"padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"margin_mobile":{"unit":"px","top":"0","right":0,"bottom":"0","left":0,"isLinked":false}},"elements":[{"id":"7b7a6d9b","elType":"column","settings":{"_column_size":100,"_inline_size":null,"padding_tablet":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"margin_tablet":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"align_tablet":"flex-start","space_between_widgets":10,"space_between_widgets_tablet":10,"_inline_size_tablet":100,"padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[{"id":"d2bfbfd","elType":"widget","settings":{"editor":"<p>October is National Bullying Prevention Month. In preschool, prevention is the name of the game. At this age, children aren’t really capable of intentionally bullying another quite yet, and they’re too young for cyber bullying. But, they will have disagreements with peers and act out of frustration. How can you help your child succeed from her very first school day? Help her build self-confidence when it comes to learning; by being her biggest cheerleader you'll instill a love of learning that will last throughout her life and will help her meet specific goals each year.</p><p>There will be focus throughout this year on mastering letters, sounds, and words. You'll watch with delight as she takes her first steps toward reading and writing correctly, especially when those activities are linked, both at school and at home. Help your kindergartner have fun with language in everyday life this year and watch as her vocabulary explodes.</p><p>She will learn key fundamentals of math this year, too, and there will be countless ways (no pun intended) to encourage this. Educational standards vary across states, districts, and schools, and no two children learn at exactly the same rate, so don't panic if your little one doesn't start to read at the same time as the neighbor's kid.</p>","typography_typography":"custom","_margin_tablet":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_padding_tablet":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"drop_cap":"yes","drop_cap_size":{"unit":"px","size":12,"sizes":[]},"drop_cap_primary_color":"var(--vamtam-accent-color-6)","drop_cap_space":{"unit":"px","size":16,"sizes":[]},"drop_cap_border_radius":{"unit":"%","size":0,"sizes":[]},"drop_cap_typography_typography":"custom","drop_cap_typography_font_size":{"unit":"px","size":83,"sizes":[]},"drop_cap_typography_line_height":{"unit":"px","size":75,"sizes":[]},"drop_cap_typography_font_weight":"bold"},"elements":[],"widgetType":"text-editor"},{"id":"7e0298f1","elType":"widget","settings":{"style":"dots_tribal","width":{"unit":"%","size":3,"sizes":[]},"align":"center","text":"Divider","color":"var(--vamtam-accent-color-4)","weight":{"unit":"px","size":2.8,"sizes":[]},"pattern_height":{"unit":"px","size":18,"sizes":[]},"gap":{"unit":"px","size":25,"sizes":[]},"width_mobile":{"unit":"%","size":12,"sizes":[]},"align_mobile":"center","gap_mobile":{"unit":"px","size":13,"sizes":[]}},"elements":[],"widgetType":"divider"},{"id":"1fb257e3","elType":"widget","settings":{"title":"Letters and Sounds","header_size":"h3","_margin_mobile":{"unit":"px","top":"10","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetTy