","isLinked":false},"align_tablet":"flex-start","margin":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"space_between_widgets":10,"space_between_widgets_tablet":10},"elements":[{"id":"11a414ee","elType":"widget","settings":{"editor":"The New Einstein’s Academy offers an innovative program for children. The curriculum is designed to empower the children through social interaction, play, discussion, reflection, and creativity. It is the best preschool in Chicago. The daily program of New Einstein’s Academy includes free play, hands-on activities, many learning and outdoor activities. The preschool also goes on field trips on a bi-monthly basis.","typography_typography":"custom","_margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"text-editor"},{"id":"5a198fb5","elType":"widget","settings":{"blockquote_skin":"quotation","alignment":"left","blockquote_content":"It's always better to start them on easier books, because then they feel successful, and that spurs them on, so they'll read more.","author_name":"John Doe","tweet_button_skin":"link","tweet_button_label":"Post on twitter","button_color_source":"custom","button_text_color":"var(--vamtam-accent-color-2)","button_text_color_hover":"var(--vamtam-accent-color-2)","box_padding":{"unit":"px","size":43,"sizes":[]},"box_border_width":{"unit":"px","top":"1","right":"1","bottom":"1","left":"1","isLinked":true},"box_border_radius":{"unit":"px","size":10,"sizes":[]},"quote_text_color":"var(--vamtam-accent-color-6)","quote_size":{"unit":"px","size":1.6,"sizes":[]},"quote_gap":{"unit":"px","size":0,"sizes":[]},"_margin":{"unit":"%","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"_padding":{"unit":"%","top":"0","right":"15","bottom":"3","left":"15","isLinked":false},"user_name":"@vamtam","author_text_color":"var(--vamtam-accent-color-6)","button_typography_typography":"custom","custom_css":"blockquote .wp-block-pullquote__citation, blockquote .wp-block-quote__citation, blockquote cite {
    margin: 0;
}","content_gap":{"unit":"px","size":0,"sizes":[]},"tweet_button_view":"icon","content_typography_typography":"custom","content_typography_font_size":{"unit":"px","size":21,"sizes":[]},"content_typography_line_height":{"unit":"em","size":1.63,"sizes":[]},"__globals__":{"box_background_color":"globals/colors?id=vamtam_accent_8"}},"elements":[],"widgetType":"blockquote"},{"id":"46f515fc","elType":"widget","settings":{"editor":"Quinn says. Dr. Seuss books, with their rhymes and simple words, are perfect for this age, Quinn says. Kids learn through repetition, so read the same favorite books over and over, ask questions, and encourage your child to say simple words aloud. Throughout the day, have her say the words she sees on street signs, billboards, and computer screens, or have her search for high-frequency words in a magazine.","typography_typography":"custom","text_columns":"1","text_columns_tablet":"1","text_columns_mobile":"1","column_gap":{"unit":"%","size":5,"sizes":[]},"_margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_margin":{"unit":"px","top":"0","right":"0","bottom":"20","left":"0","isLinked":false}},"elements":[],"widgetType":"text-editor"},{"id":"7578e75d","elType":"section","settings":{"content_position":"middle","structure":"20","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[{"id":"1da2829","elType":"column","settings":{"_column_size":50,"_inline_size":null,"space_between_widgets":0,"border_border":"solid","border_width":{"unit":"px","top":"1","right":"1","bottom":"1","left":"1","isLinked":true},"color_link":"var(--vamtam-accent-color-6)","color_link_hover":"var(--vamtam-accent-color-2)","margin":{"unit":"px","top":"0","right":"15","bottom":"0","left":"0","isLinked":false},"padding":{"unit":"px","top":"30","right":"20","bottom":"20","left":"30","isLinked":false},