ottom":"0","left":"0","isLinked":false},"margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"padding":{"unit":"px","top":"10","right":"0","bottom":"0","left":"0","isLinked":false},"align_tablet":"flex-start","margin":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"space_between_widgets":10,"space_between_widgets_tablet":10},"elements":[{"id":"217564f","elType":"widget","settings":{"editor":"The New Einstein’s Academy offers an innovative program for children. The curriculum is designed to empower the children through social interaction, play, discussion, reflection, and creativity. It is the best preschool in Chicago. The daily program of New Einstein’s Academy includes free play, hands-on activities, many learning and outdoor activities. The preschool also goes on field trips on a bi-monthly basis.","typography_typography":"custom","_margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"text-editor"},{"id":"3af2b259","elType":"widget","settings":{"editor":"<p>Quinn says. Dr. Seuss books, with their rhymes and simple words, are perfect for this age, Quinn says. Kids learn through repetition, so read the same favorite books over and over, ask questions, and encourage your child to say simple words aloud. Throughout the day, have her say the words she sees on street signs, billboards, and computer screens, or have her search for high-frequency words in a magazine.</p>","typography_typography":"custom","text_columns":"1","text_columns_tablet":"1","text_columns_mobile":"1","column_gap":{"unit":"%","size":5,"sizes":[]},"_margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_margin":{"unit":"px","top":"0","right":"0","bottom":"20","left":"0","isLinked":false}},"elements":[],"widgetType":"text-editor"},{"i