}","content_gap":{"unit":"px","size":0,"sizes":[]},"tweet_button_view":"icon","content_typography_typography":"custom","content_typography_font_size":{"unit":"px","size":21,"sizes":[]},"content_typography_line_height":{"unit":"em","size":1.63,"sizes":[]},"__globals__":{"box_background_color":"globals/colors?id=vamtam_accent_8"}},"elements":[],"widgetType":"blockquote"},{"id":"3e3622f1","elType":"widget","settings":{"editor":"Quinn says. Dr. Seuss books, with their rhymes and simple words, are perfect for this age, Quinn says. Kids learn through repetition, so read the same favorite books over and over, ask questions, and encourage your child to say simple words aloud. Throughout the day, have her say the words she sees on street signs, billboards, and computer screens, or have her search for high-frequency words in a magazine.","typography_typography":"custom","text_columns":"1","text_columns_tablet":"1","text_columns_mobile":"1","column_gap":{"unit":"%","size":5,"sizes":[]},"_margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_margin":{"unit":"px","top":"0","right":"0","bottom":"20","left":"0","isLinked":false}},"elements":[],"widgetType":"text-editor"},{"id":"67f84712","elType":"section","settings":{"content_position":"middle","structure":"20","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[{"id":"3c2ee1e7","elType":"column","settings":{"_column_size":50,"_inline_size":null,"space_between_widgets":0,"border_border":"solid","border_width":{"unit":"px","top":"1","right":"1","bottom":"1","left":"1","isLinked":true},"color_link":"var(--vamtam-accent-color-6)","color_link_hover":"var(--vamtam-accent-color-2)","margin":{"unit":"px","top":"0","right":"15","bottom":"0","left":"0","isLinked":false},"padding":{"unit":"px","top":"30","right":"20","bottom":"20","left":"30","isLinked":false}